  sub to_psgi {
    my $self = shift;

    my $request = $self->request;
    my $response = $self->response;

    my $cb = $self->cb;

    # localize the request and response
    local *Dancer2::Core::Request = $request;
    local *Dancer2::Core::Response = $response;

    # call the callback
    $cb->();

    # check if the response was changed
    if ( $response->is_changed ) {
        # create a new PSGI response
        my $psgi_response = $response->to_psgi;

        # send it to the callback
        $cb->( $psgi_response );
    }
    else {
        # send the original PSGI response
        $cb->( $response->psgi_response );
    }
}

